 [[36.0,250.0],[12.5,80.0]].forEach(([s,V])=>calc('solub',`A fictional salt has a solubility of ${s.toFixed(1)} g per 100 mL of water at 25 °C. What is the maximum mass, in g, that dissolves in ${V.toFixed(1)} mL of water at 25 °C? Round to one decimal place.`,dp(s*V/100,1),'Saturation limit',[`${s.toFixed(1)} g per 100 mL`,`${V.toFixed(1)} mL of water`,'max = s × V ÷ 100'],`The limit scales with volume: ${s.toFixed(1)} × ${V.toFixed(1)} ÷ 100 = ${dp(s*V/100,1)} g.`));
 [[80.0,150.0,28.0],[55.0,200.0,20.0]].forEach(([m,V,s])=>calc('solub',`${m.toFixed(1)} g of a fictional solute is stirred into ${V.toFixed(1)} mL of water. Its solubility is ${s.toFixed(1)} g per 100 mL at this temperature. How many grams remain undissolved? Round to one decimal place.`,dp(m-s*V/100,1),'Saturated solution',[`limit: ${s.toFixed(1)} × ${V.toFixed(1)} ÷ 100 g`,`added: ${m.toFixed(1)} g`,'undissolved = added − limit'],`Only ${dp(s*V/100,1)} g can dissolve, so ${m.toFixed(1)} − ${dp(s*V/100,1)} = ${dp(m-s*V/100,1)} g stays undissolved.`));
 calc('solub','Use these approximate textbook values for KNO₃: 64 g dissolve in 100 g of water at 40 °C and 110 g at 60 °C. A solution saturated at 60 °C contains 250 g of water. It is cooled to 40 °C with no evaporation. How many grams of KNO₃ crystallize? Round to three significant figures.',115,'Cooling a saturated solution',['at 60 °C: 110 g per 100 g × 2.5','at 40 °C: 64 g per 100 g × 2.5','crystals = difference'],'The 250 g of water holds 2.5 × 110 = 275 g at 60 °C and 2.5 × 64 = 160 g at 40 °C, so 275 − 160 = 115 g crystallize.');
 fact('solub',[
  ['How does the solubility of a gas in water usually change as the temperature rises?','it usually decreases','it usually increases','it stays the same','Warmer water gives dissolved gas molecules more kinetic energy to escape, so gases are usually less soluble when hot.'],
  ['When NaCl dissolves in water, how do the water molecules face the Na⁺ ions?','the oxygen (δ⁻) end points toward the cation','the hydrogen (δ⁺) end points toward the cation','water molecules stay away from the ions','Ion-dipole attraction: the negative end of the polar water molecule is drawn to the positive ion.'],
  ['Why does octane not dissolve in water?','dissolving would replace strong water-water hydrogen bonds with only weak attractions to the octane','octane is too dense','octane reacts with water','Water molecules attract each other more strongly than they would attract nonpolar octane, so they exclude it.']]);
 /* 3.11 spectroscopy and the electromagnetic spectrum */
 const CC='Use c = 2.998 × 10⁸ m/s and h = 6.626 × 10⁻³⁴ J·s.';
 [650,450].forEach(w=>calc('spec',`Light has a wavelength of ${w} nm. What is its frequency, in units of 10¹⁴ Hz? ${CC} ${RS}`,sf(CL/(w*1e-9)/1e14,3),'c = λν',[`λ = ${w} nm = ${w}×10⁻⁹ m`,'ν = c ÷ λ'],`ν = c ÷ λ = 2.998 × 10⁸ ÷ (${w} × 10⁻⁹) = ${sf(CL/(w*1e-9)/1e14,3)} × 10¹⁴ Hz.`));
 [7.50,3.00].forEach(v=>calc('spec',`A photon has a frequency of ${v.toFixed(2)} × 10¹⁴ Hz. What is its wavelength, in nm? ${CC} ${RS}`,sf(CL/(v*1e14)*1e9,3),'λ = c ÷ ν',[`ν = ${v.toFixed(2)}×10¹⁴ Hz`,'λ = c ÷ ν, then convert m to nm'],`λ = c ÷ ν = 2.998 × 10⁸ ÷ (${v.toFixed(2)} × 10¹⁴) m = ${sf(CL/(v*1e14)*1e9,3)} nm.`));
 [400,700,250].forEach(w=>calc('spec',`What is the energy of one photon of ${w} nm light, in units of 10⁻¹⁹ J? ${CC} ${RS}`,sf(HP*CL/(w*1e-9)/1e-19,3),'E = hc ÷ λ',[`λ = ${w} nm = ${w}×10⁻⁹ m`,'E = hc ÷ λ'],`E = hc ÷ λ = (6.626 × 10⁻³⁴)(2.998 × 10⁸) ÷ (${w} × 10⁻⁹) = ${sf(HP*CL/(w*1e-9)/1e-19,3)} × 10⁻¹⁹ J.`));
 [1.50].forEach(v=>calc('spec',`What is the energy of one photon with a frequency of ${v.toFixed(3)} × 10¹⁵ Hz, in units of 10⁻¹⁹ J? Use h = 6.626 × 10⁻³⁴ J·s. ${RS}`,sf(HP*v*1e15/1e-19,3),'E = hν',[`ν = ${v.toFixed(3)}×10¹⁵ Hz`,'E = hν'],`E = hν = (6.626 × 10⁻³⁴)(${v.toFixed(3)} × 10¹⁵) = ${sf(HP*v*1e15/1e-19,3)} × 10⁻¹⁹ J.`));
 [[450,700,'photon A'],[1200,380,'photon B']].forEach(([a,b,right],i)=>{const c=choose(right,[right==='photon A'?'photon B':'photon A','they have the same energy'],i);
  put('spec',`Photon A has a wavelength of ${a} nm and photon B has a wavelength of ${b} nm. Which photon has the greater energy? ${c.text}. Answer A, B or C.`,c.letter,board('E = hc ÷ λ',[`A: ${a} nm`,`B: ${b} nm`,'shorter wavelength, more energy']),`Energy is inversely proportional to wavelength, so the photon with the shorter wavelength (${right==='photon A'?a:b} nm) has more energy.`,[right]);});
 [['Which region of the electromagnetic spectrum has the highest-energy photons: infrared, ultraviolet or microwave?','ultraviolet','infrared','microwave'],['Which region has the lowest frequency: visible light, X-rays or radio waves?','radio waves','visible light','X-rays']].forEach(([stem,right,w1,w2],i)=>{const c=choose(right,[w1,w2],i+1);put('spec',`${stem} ${c.text}. Answer A, B or C.`,c.letter,SPEC,`Photon energy and frequency rise as wavelength falls; across the spectrum the order is radio, microwave, infrared, visible, ultraviolet, X-ray, gamma, so ${right} is the answer.`,[right]);});
 fact('spec',[
  ['What does absorption of infrared radiation by a molecule mainly change?','the vibrations of its bonds','the energy levels of its inner-shell electrons','the number of protons in its nuclei','Infrared photons have energies that match the changes in molecular vibration, which is the basis of infrared spectroscopy.'],
  ['Photons of visible and ultraviolet light can be absorbed by a molecule to cause what?','a valence electron moves to a higher energy level','a nucleus changes into a different element','all the covalent bonds break at once','Their energies match the gaps between valence electron energy levels, which is the basis of UV-visible spectroscopy.'],
  ['The wavelength of a beam of light is doubled while it stays in a vacuum. What happens to its frequency?','it is halved','it doubles','it stays the same','Since c = λν and the speed c is fixed in a vacuum, doubling the wavelength λ halves the frequency ν.']]);
 /* 3.12 photoelectric effect */
 [[1.20,3.80],[1.00,4.50],[.900,2.80]].forEach(([v,phi])=>calc('photo',`Light of frequency ${v.toFixed(2)} × 10¹⁵ Hz strikes a fictional metal whose work function is Φ = ${phi.toFixed(2)} × 10⁻¹⁹ J. What is the maximum kinetic energy of an ejected electron, in units of 10⁻¹⁹ J? Use h = 6.626 × 10⁻³⁴ J·s. ${RS}`,sf(HP*v*1e15/1e-19-phi,3),'KE = hν − Φ',[`hν = (6.626×10⁻³⁴)(${v.toFixed(2)}×10¹⁵)`,`Φ = ${phi.toFixed(2)}×10⁻¹⁹ J`,'KE = hν − Φ'],`hν = ${dp(HP*v*1e15/1e-19,3)} × 10⁻¹⁹ J, so KE = ${dp(HP*v*1e15/1e-19,3)} − ${phi.toFixed(2)} = ${sf(HP*v*1e15/1e-19-phi,3)} × 10⁻¹⁹ J.`));
 [2.50,4.20,5.00].forEach(phi=>calc('photo',`A fictional metal has a work function of ${phi.toFixed(2)} × 10⁻¹⁹ J. What is its threshold frequency, in units of 10¹⁴ Hz? Use h = 6.626 × 10⁻³⁴ J·s. ${RS}`,sf(phi*1e-19/HP/1e14,3),'ν₀ = Φ ÷ h',[`Φ = ${phi.toFixed(2)}×10⁻¹⁹ J`,'ν₀ = Φ ÷ h'],`The photon must carry at least Φ: ν₀ = Φ ÷ h = ${phi.toFixed(2)} × 10⁻¹⁹ ÷ 6.626 × 10⁻³⁴ = ${sf(phi*1e-19/HP/1e14,3)} × 10¹⁴ Hz.`));
 [4.00,5.20].forEach(phi=>calc('photo',`A fictional metal has a work function of ${phi.toFixed(2)} × 10⁻¹⁹ J. What is the longest wavelength of light, in nm, that can eject electrons? ${CC} ${RS}`,sf(HP*CL/(phi*1e-19)*1e9,3),'λ₀ = hc ÷ Φ',[`Φ = ${phi.toFixed(2)}×10⁻¹⁹ J`,'λ₀ = hc ÷ Φ, in nm'],`The threshold wavelength is λ₀ = hc ÷ Φ = (6.626 × 10⁻³⁴)(2.998 × 10⁸) ÷ (${phi.toFixed(2)} × 10⁻¹⁹) m = ${sf(HP*CL/(phi*1e-19)*1e9,3)} nm.`));
 [[6.0,5.1],[4.5,5.8],[5.0,5.4]].forEach(([v,v0],i)=>{const ej='electrons are ejected',no='no electrons are ejected, however bright the light',right=v>v0?ej:no,c=choose(right,[v>v0?no:ej,'electrons are ejected only if the light is made brighter'],i);
  put('photo',`Light of frequency ${v.toFixed(1)} × 10¹⁴ Hz shines on a metal whose threshold frequency is ${v0.toFixed(1)} × 10¹⁴ Hz. What happens? ${c.text}. Answer A, B or C.`,c.letter,board('Compare with the threshold',[`light: ${v.toFixed(1)}×10¹⁴ Hz`,`threshold: ${v0.toFixed(1)}×10¹⁴ Hz`]),`Electrons are ejected only when the frequency is at least the threshold frequency; here ${v} is ${v>v0?'above':'below'} ${v0}, so ${right}.`,[right]);});
 fact('photo',[
  ['Light above the threshold frequency has its intensity doubled. What changes?','twice as many electrons are ejected, each with the same maximum kinetic energy','the same number of electrons is ejected, each with twice the kinetic energy','more electrons are ejected and each has more kinetic energy','Intensity is the number of photons per second; each photon still ejects one electron with the same maximum energy hν − Φ.'],
  ['What does the photoelectric effect provide evidence for?','that light can behave as particles, each photon transferring its energy to one electron','that light has no energy','that electrons are heavier than photons','A threshold frequency independent of intensity fits photons of energy hν, not a continuous wave that builds up energy.'],
  ['What is the work function of a metal?','the minimum energy needed to remove an electron from the metal','the maximum kinetic energy of ejected electrons','the energy of the brightest light used','The work function Φ is the binding energy that a photon must supply before any kinetic energy is left over.']]);
 /* 3.13 Beer-Lambert law */
 [[1.50,1.00,2.0],[.850,2.00,3.5]].forEach(([e,b,c])=>calc('beer',`A fictional dye has ε = ${e.toFixed(2)} × 10⁴ L/(mol·cm). What is the absorbance in a ${b.toFixed(2)} cm cell at ${c.toFixed(1)} × 10⁻⁵ M? Use A = εbc. ${RS}`,sf(e*1e4*b*c*1e-5,3),'A = εbc',[`ε = ${e.toFixed(2)}×10⁴, b = ${b.toFixed(2)} cm`,`c = ${c.toFixed(1)}×10⁻⁵ M`,'A = εbc'],`A = εbc = (${e.toFixed(2)} × 10⁴)(${b.toFixed(2)})(${c.toFixed(1)} × 10⁻⁵) = ${sf(e*1e4*b*c*1e-5,3)}; absorbance has no units.`));
 [[.450,1.50,1.00],[.660,1.10,2.00]].forEach(([A,e,b])=>calc('beer',`A fictional dye has ε = ${e.toFixed(2)} × 10⁴ L/(mol·cm). A sample in a ${b.toFixed(2)} cm cell has absorbance ${A.toFixed(3)}. What is its concentration, in units of 10⁻⁵ M? ${RS}`,sf(A/(e*1e4*b)/1e-5,3),'c = A ÷ εb',[`A = ${A.toFixed(3)}`,`ε = ${e.toFixed(2)}×10⁴, b = ${b.toFixed(2)} cm`,'c = A ÷ (εb)'],`c = A ÷ (εb) = ${A.toFixed(3)} ÷ (${e.toFixed(2)} × 10⁴ × ${b.toFixed(2)}) = ${sf(A/(e*1e4*b)/1e-5,3)} × 10⁻⁵ M.`));
 [[.540,1.00,2.0]].forEach(([A,b,c])=>calc('beer',`A solution of a fictional compound at ${c.toFixed(1)} × 10⁻⁵ M has absorbance ${A.toFixed(3)} in a ${b.toFixed(2)} cm cell. What is its molar absorptivity ε, in units of 10⁴ L/(mol·cm)? ${RS}`,sf(A/(b*c*1e-5)/1e4,3),'ε = A ÷ bc',[`A = ${A.toFixed(3)}, b = ${b.toFixed(2)} cm`,`c = ${c.toFixed(1)}×10⁻⁵ M`,'ε = A ÷ (bc)'],`ε = A ÷ (bc) = ${A.toFixed(3)} ÷ (${b.toFixed(2)} × ${c.toFixed(1)} × 10⁻⁵) = ${sf(A/(b*c*1e-5)/1e4,3)} × 10⁴ L/(mol·cm).`));
 [.301,1.000,.500].forEach(A=>calc('beer',`A sample has an absorbance of ${A.toFixed(3)}. What percent of the light is transmitted, using T = 10^(−A)? Round to three significant figures.`,sf(100*10**-A,3),'Transmittance',[`A = ${A.toFixed(3)}`,'T = 10^(−A)','percent = 100 × T'],`T = 10^(−${A.toFixed(3)}) = ${dp(10**-A,4)}, so ${sf(100*10**-A,3)} percent of the light is transmitted.`));
 [[.320,2.0,.800],[.240,3.0,.600]].forEach(([a1,c1,a2])=>calc('beer',`In the same cell, a fictional dye at ${c1.toFixed(1)} × 10⁻⁵ M has absorbance ${a1.toFixed(3)}. A second sample has absorbance ${a2.toFixed(3)}. What is its concentration, in units of 10⁻⁵ M? ${RS}`,sf(c1*a2/a1,3),'A is proportional to c',[`A₁ = ${a1.toFixed(3)} at ${c1.toFixed(1)}×10⁻⁵ M`,`A₂ = ${a2.toFixed(3)}`,'c₂ = c₁ × A₂ ÷ A₁'],`With ε and b fixed, A is proportional to c: c₂ = ${c1.toFixed(1)} × ${a2.toFixed(3)} ÷ ${a1.toFixed(3)} = ${sf(c1*a2/a1,3)} × 10⁻⁵ M.`));
 calc('beer','A solution has an absorbance of 0.250 in a 1.00 cm cell. What absorbance would the same solution give in a 3.00 cm cell? Round to three significant figures.',.75,'A is proportional to b',['A = 0.250 at b = 1.00 cm','b = 3.00 cm'],'Absorbance is proportional to path length at fixed concentration, so A = 0.250 × 3.00 = 0.750.');
 fact('beer',[
  ['The concentration of an absorbing solution is doubled in the same cell at the same wavelength. What happens to the absorbance?','it doubles','it is halved','it stays the same','A = εbc, so with ε and b fixed, absorbance is directly proportional to concentration.'],
  ['Why is an absorbance measurement usually made at the wavelength of maximum absorbance?','the absorbance is largest there, which gives the best sensitivity','the transmittance is largest there','every substance absorbs only at that wavelength','Near the peak, absorbance changes most with concentration and is least sensitive to small errors in wavelength.'],
  ['What are the units of absorbance, A?','none, it is a unitless ratio','mol/L','L/(mol·cm)','A = −log₁₀ T is the logarithm of a ratio of light intensities, so it has no units.']]);
